mapper.select:
select a.*, ww.warehouse_name, b.product_name, wco.owner_name, wsio.order_number as stock_in_order_number
from wms_tasks a
left join wms_warehouses ww on a.target_warehouse_id = ww.id
left join wms_products b on a.product_id = b.id
left join wms_cargo_owners wco on b.owner_id = wco.id
left join wms_stock_in_orders wsio on a.stock_in_order_id = wsio.id



        and a.task_number = #{task.taskNumber}



        and a.task_type = #{task.taskType}



        and a.task_status = #{task.taskStatus}



        and wsio.order_number = #{task.stockInOrderNumber}



        and a.stock_in_order_id = #{task.stockInOrderId}



        and a.wave_order_id = #{task.waveOrderId}



        and a.operator = #{task.operator}


order by a.create_time desc, a.task_number desc
